$('#sort').innerHTML='<option value="new">Application term: newest</option><option value="old">Application term: oldest</option><option value="submitted">Recently submitted</option><option value="high">GPA: high to low</option><option value="low">GPA: low to high</option>';
const storyNav=document.createElement('a');storyNav.href='#story';storyNav.id='nav-story';storyNav.textContent='Our Story';nav.append(storyNav);
const storyPage=document.createElement('section');storyPage.id='our-story';storyPage.hidden=true;
storyPage.innerHTML=`<div class="page-heading"><h1>There is more than one way to college.</h1><p>Why I started this project.</p></div><article class="founder-story"><p class="story-kicker">AN INTERNATIONAL STUDENT’S PERSPECTIVE</p><h2>From a disappointing result to a different beginning.</h2><p>I’m an international student, and my path to university did not begin the way I had hoped. I did poorly on my high school exams, and at the time, I felt that community college was my only option.</p><p>I chose Northern Virginia Community College (NVCC, also known as NOVA). From there, I transferred to George Mason University to study Computer Science.</p><p>That experience is why I wanted to build this website. I want students considering a similar path to see more than a university name or an admission decision. The background matters too: GPA, previous college, activities, competitions, English test scores when relevant, and what happened at each school.</p><h2>A place to understand different paths.</h2><p>The goal is to make transfer experiences easier to find and compare, especially for international students who may be unsure where to begin. I hope students can share both the outcomes and the context behind them, including the setbacks.</p><p>A disappointing exam result does not have to be the end of your education story. Community college can be a meaningful starting point, and transferring can open another path forward.</p><div class="story-note"><strong>Where the project stands</strong><p>This is an early prototype. Current example profiles are fictional and clearly labeled. Submissions stay in your browser; a public community has not launched yet. Shared experiences are context, not admission guarantees.</p></div><a class="primary" href="#explore">Explore transfer stories</a></article>`;
schoolSection.after(storyPage);
const existingRoute=route;
route=function(){existingRoute();const isStory=location.hash==='#story';storyPage.hidden=!isStory;storyNav.classList.toggle('active',isStory);if(isStory){for(const id of ['explore','share','universities','university-detail'])$('#'+id).hidden=true;for(const id of ['explore','share','universities'])$('#nav-'+id).classList.remove('active');$('#crumb').textContent='Our Story';}};
render();route();
